values ('ap_chemistry', 4, '4.7', array['4.7', '4.8', '4.9']::text[], 'list_sequence', 'Three reaction types and what defines them', 'Identify a reaction as acid-base, oxidation-reduction (redox), or precipitation by what is transferred or formed.', '[{"label": "Acid-base", "meaning": "Transfer of one or more protons (H+ ions) between chemical species."}, {"label": "Oxidation-reduction (redox)", "meaning": "Transfer of one or more electrons between chemical species, shown by changes in oxidation numbers; electrons go from the species oxidized to the species reduced. Combustion is a redox subclass, and complete combustion of a hydrocarbon gives CO2 and H2O."}, {"label": "Precipitation", "meaning": "Mixing ions in aqueous solution produces an insoluble or sparingly soluble ionic compound. All sodium, potassium, ammonium, and nitrate salts are soluble."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_chemistry-u4-r2-001; ced=4.7.A.1, 4.7.A.2, 4.7.A.3, 4.7.A.4, 4.7.A.5')
